-- Delivery database schema (generated by build_db.py). Policy: unknown values are the string N/A, never NULL.
CREATE VIEW v_case_timeline AS
SELECT case_id, timestamp AS at, 'message' AS kind, message_id AS id, stage AS type, from_raw AS source, body AS text, visible_at_escalation FROM messages
UNION ALL
SELECT case_id, occurred_at AS at, 'event' AS kind, event_id AS id, event_type AS type, source_system AS source, text, visible_at_escalation FROM events
ORDER BY case_id, at;

CREATE VIEW v_decision_input AS
SELECT c.case_id, c.title, c.raised_by, c.channel, c.linked_object_id, c.request_or_claim,
       m.seq, m.timestamp, m.channel AS message_channel, m.from_raw, m.body
FROM cases c JOIN messages m ON m.case_id = c.case_id WHERE m.visible_at_escalation = 1;

CREATE VIEW v_shipment_dashboard AS
SELECT s.shipment_id AS shipment_id, s.shipment_id AS shipment, s.order_id AS "order",
       s.milestone_final AS current_milestone, s.milestone_at_escalation AS milestone_at_escalation, s.exception AS exception,
       CASE WHEN s.milestone_final IN ('Delivered', 'Collected', 'Lost') THEN 'none recorded (case closed)' ELSE c.recorded_next_action END AS next_action,
       c.recorded_next_action AS next_action_at_escalation,
       CASE WHEN s.milestone_final IN ('Delivered', 'Collected', 'Lost') THEN 'N/A' ELSE c.owner_group END AS owner,
       c.owner_group AS owner_at_escalation, c.owner AS owner_team_at_escalation,
       CASE WHEN s.milestone_final IN ('Delivered', 'Collected', 'Lost') THEN 'N/A (completed)' ELSE s.promised_at END AS eta,
       s.promised_at AS promised_window, c.case_state_final AS case_state, s.case_id AS case_id, c.queue AS queue, c.human_gate AS human_gate, c.deadline AS deadline,
       c.complexity_level AS complexity_level, c.complexity_name AS complexity_name, c.stress_theme AS stress_theme
FROM shipments s LEFT JOIN cases c ON c.case_id = s.case_id;

CREATE TABLE actors (actor_id TEXT PRIMARY KEY, name TEXT NOT NULL, party TEXT NOT NULL, org TEXT NOT NULL, org_type TEXT NOT NULL, role TEXT NOT NULL, is_person INTEGER NOT NULL);

CREATE TABLE case_actors (case_id TEXT NOT NULL REFERENCES cases(case_id), actor_id TEXT NOT NULL REFERENCES actors(actor_id), role_in_case TEXT NOT NULL, PRIMARY KEY (case_id, actor_id, role_in_case));

CREATE TABLE cases (case_id TEXT PRIMARY KEY, source_set TEXT NOT NULL, labelled INTEGER NOT NULL, title TEXT NOT NULL, created_at TEXT NOT NULL, escalated_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT NOT NULL, case_type TEXT NOT NULL, case_category TEXT NOT NULL, raised_by TEXT NOT NULL, raised_by_type TEXT NOT NULL, raised_by_actor_id TEXT NOT NULL, channel TEXT NOT NULL, channel_class TEXT NOT NULL, linked_object_id TEXT NOT NULL, linked_object_type TEXT NOT NULL, request_or_claim TEXT NOT NULL, requested_action_by_raiser TEXT NOT NULL, recorded_next_action TEXT NOT NULL, recorded_action_message_id TEXT NOT NULL, case_state_at_escalation TEXT NOT NULL, case_state_final TEXT NOT NULL, operational_effect TEXT NOT NULL, priority TEXT NOT NULL, urgency TEXT NOT NULL, cutoff_utc TEXT NOT NULL, deadline TEXT NOT NULL, owner TEXT NOT NULL, owner_group TEXT NOT NULL, owner_function TEXT NOT NULL, owner_actor_id TEXT NOT NULL, gold_channel TEXT NOT NULL, action_class TEXT NOT NULL, proof_standard TEXT NOT NULL, queue TEXT NOT NULL, human_gate TEXT NOT NULL, resolution TEXT NOT NULL, boundaries TEXT NOT NULL, context_summary TEXT NOT NULL, grading_reference TEXT NOT NULL, segment TEXT NOT NULL, requester_type TEXT NOT NULL, shipment_stage TEXT NOT NULL, owner_org_type TEXT NOT NULL, customer_input_required TEXT NOT NULL, risk_flags TEXT NOT NULL, money_involved TEXT NOT NULL, amount_gbp_known TEXT NOT NULL, verification_state TEXT NOT NULL, evidence_conflict TEXT NOT NULL, refs_at_escalation TEXT NOT NULL, n_messages INTEGER NOT NULL, source_dir TEXT NOT NULL, complexity_level TEXT NOT NULL, complexity_name TEXT NOT NULL, stress_theme TEXT NOT NULL, label_source TEXT NOT NULL);

CREATE TABLE events (event_id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(case_id), shipment_id TEXT NOT NULL, event_type TEXT NOT NULL, location TEXT NOT NULL, occurred_at TEXT NOT NULL, time_precision TEXT NOT NULL, is_planned INTEGER NOT NULL, source_system TEXT NOT NULL, source_message_id TEXT NOT NULL REFERENCES messages(message_id), visible_at_escalation INTEGER NOT NULL, text TEXT NOT NULL, extraction TEXT NOT NULL);

CREATE TABLE evidence (evidence_id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(case_id), shipment_id TEXT NOT NULL, evidence_type TEXT NOT NULL, reference TEXT NOT NULL, description TEXT NOT NULL, source TEXT NOT NULL, file_name TEXT NOT NULL, first_seen_message_id TEXT NOT NULL, visible_at_escalation INTEGER NOT NULL);

CREATE TABLE messages (message_id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(case_id), seq INTEGER NOT NULL, timestamp TEXT NOT NULL, stage TEXT NOT NULL, channel TEXT NOT NULL, from_actor_id TEXT NOT NULL REFERENCES actors(actor_id), from_raw TEXT NOT NULL, from_org_type TEXT NOT NULL, to_actor_ids TEXT NOT NULL, direction TEXT NOT NULL, visible_at_escalation INTEGER NOT NULL, body TEXT NOT NULL, refs TEXT NOT NULL, amounts_gbp TEXT NOT NULL);

CREATE TABLE orders (order_id TEXT PRIMARY KEY, merchant_id TEXT NOT NULL, customer_id TEXT NOT NULL, order_status TEXT NOT NULL, case_id TEXT NOT NULL REFERENCES cases(case_id), note TEXT NOT NULL);

CREATE TABLE parcels (parcel_id TEXT PRIMARY KEY, shipment_id TEXT NOT NULL REFERENCES shipments(shipment_id), barcode TEXT NOT NULL, parcel_status TEXT NOT NULL, case_id TEXT NOT NULL REFERENCES cases(case_id), note TEXT NOT NULL);

CREATE TABLE reconciliation (entity TEXT NOT NULL, field TEXT NOT NULL, andrey_definition TEXT NOT NULL, source_in_data TEXT NOT NULL, table_column TEXT NOT NULL, coverage_n INTEGER NOT NULL, coverage_total INTEGER NOT NULL, coverage_pct REAL NOT NULL, na_policy TEXT NOT NULL, note TEXT NOT NULL);

CREATE TABLE shipments (shipment_id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(case_id), order_id TEXT NOT NULL, carrier_id TEXT NOT NULL, kind TEXT NOT NULL, milestone_at_escalation TEXT NOT NULL, milestone_final TEXT NOT NULL, exception TEXT NOT NULL, destination TEXT NOT NULL, promised_at TEXT NOT NULL, model_gap TEXT NOT NULL, shipper TEXT NOT NULL, consignee TEXT NOT NULL, note TEXT NOT NULL);

CREATE TABLE tasks (task_id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(case_id), task_type TEXT NOT NULL, description TEXT NOT NULL, assignee TEXT NOT NULL, assignee_org_type TEXT NOT NULL, channel TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT NOT NULL, status TEXT NOT NULL, source_message_id TEXT NOT NULL, is_gold_action INTEGER NOT NULL, confirmation_message_id TEXT NOT NULL);

CREATE INDEX idx_events_case ON events(case_id, occurred_at);

CREATE INDEX idx_messages_case ON messages(case_id, seq);

CREATE INDEX idx_shipments_case ON shipments(case_id);

